DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT105-S1-Q26$batch01$ AND q.stimulus=$batch01$Marion knows that the bridge on her usual route is closed and that, unless she takes the train instead of driving, she can get to work on time only by leaving at least 45 minutes early. She must go to her neighborhood bank before leaving for work, however, and the bank will not be open in time for her to do so if she leaves 45 minutes early. Therefore, since she hates taking the train, Marion cannot avoid being late for work.$batch01$ AND q.prompt=$batch01$The reasoning in the argument is flawed because the argument$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT105-S1-Q26'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT105-S1-Q26$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S1-Q26'; END IF; END $guard$;
