DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S1-Q26$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$ignores the fact that people often know that something is the case without considering all the consequences that follow from its being the case$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S1-Q26 B'; END IF; END $guard$;
